export default function FindSponsorsPage() {
  const router = useRouter();
  const [filters, setFilters] = useState<SponsorFilters>({
    industries: [],
    budgetRange: { min: 0, max: 1000000 },
    location: '',
  });

  const [filteredSponsors, setFilteredSponsors] = useState<Sponsor[]>(sponsorData);
  const [matchScores, setMatchScores] = useState<Record<string, number>>({});
  const [selectedSponsor, setSelectedSponsor] = useState<Sponsor | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    // Apply filters
    let filtered = sponsorData;

    // Filter by industry
    if (filters.industries.length > 0) {
      filtered = filtered.filter((sponsor) =>
        filters.industries.includes(sponsor.industry)
      );
    }

    // Filter by budget range
    filtered = filtered.filter(
      (sponsor) =>
        sponsor.budgetRange.max >= filters.budgetRange.min &&
        sponsor.budgetRange.min <= filters.budgetRange.max
    );

    // Filter by location
    if (filters.location) {
      filtered = filtered.filter((sponsor) =>
        sponsor.location.toLowerCase().includes(filters.location.toLowerCase())
      );
    }

    setFilteredSponsors(filtered);

    // Calculate match scores using the matching algorithm
    const currentEvent = {
      id: 'event-1',
      organizerId: 'user-1',
      name: 'Tech Innovation Summit',
      category: 'hackathon' as const,
      location: 'San Francisco, CA',
      audienceSize: 500,
      date: new Date('2024-06-15'),
      description: 'A premier technology event',
      sponsorshipRequirements: 'Looking for tech sponsors',
      status: 'published' as const,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    const scores: Record<string, number> = {};
    filtered.forEach((sponsor) => {
      const result = calculateMatchScore(currentEvent, sponsor);
      scores[sponsor.id] = result.score;
    });
    setMatchScores(scores);
  }, [filters]);

  const handleConnect = (sponsorId: string) => {
    const sponsor = filteredSponsors.find((s) => s.id === sponsorId);
    if (sponsor) {
      setSelectedSponsor(sponsor);
      setIsModalOpen(true);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <motion.div {...fadeInUp}>
        <h1 className="text-4xl font-bold bg-gradient-to-r from-[#667eea] to-[#764ba2] bg-clip-text text-transparent mb-2">
          Find Sponsors
        </h1>
        <p className="text-gray-600">
          Discover sponsors that match your event requirements
        </p>
      </motion.div>

      {/* Split View Layout */}
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Left Side - Filters */}
        <motion.div
          className="lg:col-span-1"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5 }}
        >
          <FilterPanel filters={filters} onFilterChange={setFilters} />
        </motion.div>

        {/* Right Side - Sponsor Cards */}
        <motion.div
          className="lg:col-span-3"
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5 }}
        >
          {/* Results Header */}
          <div className="mb-6">
            <p className="text-gray-700">
              <span className="font-semibold">{filteredSponsors.length}</span> sponsors found
            </p>
          </div>

          {/* Sponsor Cards Grid */}
          {filteredSponsors.length === 0 ? (
            <div className="text-center py-12 bg-white/20 backdrop-blur-md rounded-3xl border border-white/20">
              <Search size={48} className="mx-auto text-gray-400 mb-4" />
              <h3 className="text-xl font-semibold text-gray-700 mb-2">
                No sponsors found
              </h3>
              <p className="text-gray-600">
                Try adjusting your filters to see more results
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {filteredSponsors.map((sponsor) => (
                <motion.div
                  key={sponsor.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.3 }}
                >
                  <SponsorCard
                    sponsor={sponsor}
                    matchPercentage={matchScores[sponsor.id] || 0}
                    onConnect={() => handleConnect(sponsor.id)}
                  />
                </motion.div>
              ))}
            </div>
          )}
        </motion.div>
      </div>

      {/* Sponsor Details Modal */}
      <SponsorDetailsModal
        sponsor={selectedSponsor}
        matchScore={selectedSponsor ? matchScores[selectedSponsor.id] || 0 : 0}
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        eventId="event-1"
      />
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Send } from 'lucide-react';
import { ConversationList } from '@/components/chat/ConversationList';
import { MessageList } from '@/components/chat/MessageList';
import { createClient } from '@/utils/supabase/client';
import { useChat } from '@/hooks/useChat';
import { useConversations } from '@/hooks/useConversations';

function ChatArea({ conversationId, conversations, onBack }: { conversationId: string | null; conversations: any[]; onBack?: () => void }) {
  const [newMessage, setNewMessage] = useState('');
  const [currentUserId, setCurrentUserId] = useState<string>('');
  const { messages, loading, sendMessage } = useChat(conversationId);
  const supabase = createClient();

  useEffect(() => {
    const getUser = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) setCurrentUserId(user.id);
    };
    getUser();
  }, [supabase]);

  const handleSend = async () => {
    if (!newMessage.trim()) return;
    await sendMessage(newMessage.trim());
    setNewMessage('');
  };

  if (!conversationId) {
    return (
      <div className="flex-1 glass-card flex items-center justify-center text-gray-500">
        Select a conversation to start chatting
      </div>
    );
  }

  const conversation = conversations.find(c => c.id === conversationId);

  return (
    <div className="flex-1 glass-card flex flex-col">
      <div className="p-3 sm:p-4 border-b border-white/20">
        <div className="flex items-center gap-3">
          {onBack && (
            <button onClick={onBack} className="lg:hidden p-1 hover:bg-white/20 rounded-lg">
              ←
            </button>
          )}
          <h3 className="font-semibold text-base sm:text-lg">{conversation?.participantName}</h3>
        </div>
      </div>
      {loading ? (
        <div className="flex-1 flex items-center justify-center text-gray-500">Loading...</div>
      ) : (
        <MessageList messages={messages.map(m => ({ id: m.id, senderId: m.sender_id, content: m.content, timestamp: new Date(m.created_at) }))} currentUserId={currentUserId} />
      )}
      <div className="p-3 sm:p-4 border-t border-white/20">
        <div className="flex gap-2">
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type a message..."
            className="flex-1 glass-input text-sm sm:text-base"
          />
          <button onClick={handleSend} disabled={!newMessage.trim()} className="glass-button-primary px-3 sm:px-6 disabled:opacity-50">
            <Send size={16} className="sm:w-5 sm:h-5" />
          </button>
        </div>
      </div>
    </div>
  );
}

