      },
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    const scores: Record<string, number> = {};
    filtered.forEach((event) => {
      const result = calculateMatchScore(event, currentSponsor);
      scores[event.id] = result.score;
    });
    setMatchScores(scores);
  }, [filters]);

  const handleViewDetails = (eventId: string) => {
