'use client';

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Upload, X, Image as ImageIcon } from 'lucide-react';
import { GlassCard } from '@/components/shared/GlassCard';
import { GlassButton } from '@/components/shared/GlassButton';
import { Input } from '@/components/ui/Input';
import { Select } from '@/components/ui/Select';
import { Textarea } from '@/components/ui/Textarea';
import { EventCategory } from '@/types/event';

interface EventFormData {
  name: string;
  category: EventCategory | '';
  location: string;
  audienceSize: string;
  date: string;
  description: string;
  sponsorshipRequirements: string;
  banner?: File;
}

interface EventFormErrors {
  name?: string;
  category?: string;
  location?: string;
  audienceSize?: string;
  date?: string;
  description?: string;
  sponsorshipRequirements?: string;
}

interface EventFormProps {
  onSubmit: (data: EventFormData) => Promise<void>;
  onCancel?: () => void;
}

const categoryOptions = [
  { value: '', label: 'Select a category' },
  { value: 'college-fest', label: 'College Fest' },
  { value: 'competition', label: 'Competition' },
  { value: 'sports', label: 'Sports' },
  { value: 'hackathon', label: 'Hackathon' },
  { value: 'cultural', label: 'Cultural' },
  { value: 'workshop', label: 'Workshop' },
];

export function EventForm({ onSubmit, onCancel }: EventFormProps) {
  const [currentStep, setCurrentStep] = useState(1);
  const [formData, setFormData] = useState<EventFormData>({
    name: '',
    category: '',
    location: '',
    audienceSize: '',
    date: '',
    description: '',
    sponsorshipRequirements: '',
  });

  const [errors, setErrors] = useState<EventFormErrors>({});
  const [bannerPreview, setBannerPreview] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const totalSteps = 3;
  const stepTitles = [
    'Basic Information',
    'Event Details',
    'Banner & Review'
  ];

  const handleInputChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    // Clear error when user starts typing
    if (errors[name as keyof EventFormErrors]) {
      setErrors((prev) => ({ ...prev, [name]: undefined }));
    }
  };

  const handleBannerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFormData((prev) => ({ ...prev, banner: file }));

      // Create preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setBannerPreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const removeBanner = () => {
    setFormData((prev) => ({ ...prev, banner: undefined }));
    setBannerPreview(null);
  };

  const validateStep = (step: number): boolean => {
    const newErrors: EventFormErrors = {};

    if (step === 1) {
      if (!formData.name.trim()) newErrors.name = 'Event name is required';
      if (!formData.category) newErrors.category = 'Please select a category';
      if (!formData.location.trim()) newErrors.location = 'Location is required';
      if (!formData.audienceSize) {
        newErrors.audienceSize = 'Audience size is required';
      } else if (parseInt(formData.audienceSize) <= 0) {
        newErrors.audienceSize = 'Audience size must be a positive number';
      }
      if (!formData.date) {
        newErrors.date = 'Event date is required';
      } else {
        const selectedDate = new Date(formData.date);
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        if (selectedDate < today) {
          newErrors.date = 'Event date must be in the future';
        }
      }
    }

    if (step === 2) {
      if (!formData.description.trim()) newErrors.description = 'Description is required';
      if (!formData.sponsorshipRequirements.trim()) newErrors.sponsorshipRequirements = 'Sponsorship requirements are required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const nextStep = () => {
    if (validateStep(currentStep)) {
      setCurrentStep(prev => Math.min(prev + 1, totalSteps));
    }
  };

  const prevStep = () => {
    setCurrentStep(prev => Math.max(prev - 1, 1));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (currentStep < totalSteps) {
      nextStep();
      return;
    }

    setIsSubmitting(true);
    try {
      await onSubmit(formData);
    } catch (error) {
      console.error('Form submission error:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const renderStep = () => {
    switch (currentStep) {
      case 1:
        return (
          <div className="space-y-6">
            <Input
              label="Event Name"
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              placeholder="e.g., Tech Innovation Summit 2024"
              error={errors.name}
              required
            />

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Select
                label="Category"
                name="category"
                value={formData.category}
                onChange={handleInputChange}
                options={categoryOptions}
                error={errors.category}
                required
              />

              <Input
                label="Location"
                name="location"
                value={formData.location}
                onChange={handleInputChange}
                placeholder="e.g., San Francisco, CA"
                error={errors.location}
                required
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Input
                label="Expected Audience Size"
                name="audienceSize"
                type="number"
                value={formData.audienceSize}
                onChange={handleInputChange}
                placeholder="e.g., 500"
                error={errors.audienceSize}
                min="1"
                required
              />

              <Input
                label="Event Date"
                name="date"
                type="date"
                value={formData.date}
                onChange={handleInputChange}
                error={errors.date}
                required
              />
            </div>
          </div>
        );

      case 2:
        return (
          <div className="space-y-6">
            <Textarea
              label="Description"
              name="description"
              value={formData.description}
              onChange={handleInputChange}
              placeholder="Describe your event, its purpose, and what makes it unique..."
              error={errors.description}
              rows={5}
              required
            />

            <Textarea
              label="Sponsorship Requirements"
              name="sponsorshipRequirements"
              value={formData.sponsorshipRequirements}
              onChange={handleInputChange}
              placeholder="What are you looking for in a sponsor? What benefits can you offer?"
              error={errors.sponsorshipRequirements}
              rows={4}
              required
            />
          </div>
        );

      case 3:
        return (
          <div className="space-y-6">
            {bannerPreview ? (
              <div className="relative">
                <div className="relative w-full h-64 rounded-2xl overflow-hidden">
                  <img
                    src={bannerPreview}
                    alt="Banner preview"
                    className="w-full h-full object-cover"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/40 to-transparent" />
                </div>
                <button
                  type="button"
                  onClick={removeBanner}
                  className="absolute top-3 right-3 p-2 rounded-full bg-red-500 text-white hover:bg-red-600 transition-colors"
                >
                  <X size={20} />
                </button>
              </div>
            ) : (
              <label className="block">
                <div className="border-2 border-dashed border-white/40 rounded-2xl p-12 text-center cursor-pointer hover:border-[#667eea]/50 hover:bg-white/10 transition-all">
                  <Upload size={48} className="mx-auto text-gray-400 mb-4" />
                  <p className="text-gray-700 font-medium mb-2">
                    Click to upload event banner (Optional)
                  </p>
                  <p className="text-sm text-gray-600">
                    PNG, JPG up to 10MB
                  </p>
                </div>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleBannerChange}
                  className="hidden"
                />
              </label>
            )}

            {/* Review Summary */}
            <div className="bg-white/20 rounded-xl p-4 space-y-2">
              <h4 className="font-semibold text-gray-800">Review Your Event</h4>
              <div className="text-sm text-gray-600 space-y-1">
                <p><strong>Name:</strong> {formData.name}</p>
                <p><strong>Category:</strong> {categoryOptions.find(c => c.value === formData.category)?.label}</p>
                <p><strong>Location:</strong> {formData.location}</p>
                <p><strong>Date:</strong> {formData.date}</p>
                <p><strong>Audience:</strong> {formData.audienceSize} people</p>
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="glass-card p-4 sm:p-6 lg:p-8">
        <div className="space-y-6 sm:space-y-8">
          {/* Progress Steps */}
          <div className="flex items-center justify-between mb-8">
            {Array.from({ length: totalSteps }, (_, i) => i + 1).map((step) => (
              <div key={step} className="flex items-center">
                <div
                  className={`w-8 h-8 sm:w-10 sm:h-10 rounded-full flex items-center justify-center text-sm sm:text-base font-semibold transition-all ${
                    step <= currentStep
                      ? 'bg-gradient-to-r from-[#667eea] to-[#764ba2] text-white'
                      : 'bg-gray-200 text-gray-500'
                  }`}
                >
                  {step}
                </div>
                {step < totalSteps && (
                  <div
                    className={`w-12 sm:w-20 h-1 mx-2 transition-all ${
                      step < currentStep ? 'bg-gradient-to-r from-[#667eea] to-[#764ba2]' : 'bg-gray-200'
                    }`}
                  />
                )}
              </div>
            ))}
          </div>

          {/* Form Header */}
          <div className="text-center">
            <h2 className="text-xl sm:text-2xl font-bold text-gray-900 mb-2">{stepTitles[currentStep - 1]}</h2>
            <p className="text-gray-600 text-sm sm:text-base">Step {currentStep} of {totalSteps}</p>
          </div>

          {/* Step Content */}
          {renderStep()}

          {/* Form Actions */}
          <div className="flex items-center justify-between pt-6 border-t border-white/30">
            <div className="flex gap-3">
              {onCancel && (
                <button
                  type="button"
                  onClick={onCancel}
                  disabled={isSubmitting}
                  className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors text-sm sm:text-base"
                >
                  Cancel
                </button>
              )}
              {currentStep > 1 && (
                <button
                  type="button"
                  onClick={prevStep}
                  disabled={isSubmitting}
                  className="px-4 sm:px-6 py-2 bg-gray-200 text-gray-700 rounded-xl font-medium hover:bg-gray-300 transition-colors text-sm sm:text-base"
                >
                  Back
                </button>
              )}
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="px-6 sm:px-8 py-2 sm:py-3 bg-gradient-to-r from-[#667eea] to-[#764ba2] text-white rounded-xl font-medium hover:shadow-lg transition-all text-sm sm:text-base touch-manipulation"
            >
              {isSubmitting ? 'Creating...' : currentStep === totalSteps ? 'Create Event' : 'Next'}
            </button>
          </div>
        </div>
      </div>
    </form>
  );
}

'use client';

import React from 'react';
import { motion } from 'framer-motion';
import { Filter, X } from 'lucide-react';
import { GlassCard } from '@/components/shared/GlassCard';
import { GlassButton } from '@/components/shared/GlassButton';

export interface SponsorFilters {
  industries: string[];
  budgetRange: {
    min: number;
    max: number;
  };
  location: string;
}

interface FilterPanelProps {
  filters: SponsorFilters;
  onFilterChange: (filters: SponsorFilters) => void;
}

const industryOptions = [
  'Technology',
  'Finance',
  'Healthcare',
  'Education',
  'Retail',
  'Food & Beverage',
  'Entertainment',
  'Sports',
  'Fashion',
  'Automotive',
];

export function FilterPanel({ filters, onFilterChange }: FilterPanelProps) {
  const handleIndustryToggle = (industry: string) => {
    const newIndustries = filters.industries.includes(industry)
      ? filters.industries.filter((i) => i !== industry)
      : [...filters.industries, industry];

    onFilterChange({
      ...filters,
      industries: newIndustries,
    });
  };

  const handleBudgetChange = (type: 'min' | 'max', value: string) => {
    const numValue = parseInt(value) || 0;
    onFilterChange({
      ...filters,
      budgetRange: {
        ...filters.budgetRange,
        [type]: numValue,
      },
    });
  };

  const handleLocationChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onFilterChange({
      ...filters,
      location: e.target.value,
    });
  };

  const clearFilters = () => {
    onFilterChange({
      industries: [],
      budgetRange: { min: 0, max: 1000000 },
      location: '',
    });
  };

  const hasActiveFilters =
    filters.industries.length > 0 ||
    filters.budgetRange.min > 0 ||
    filters.budgetRange.max < 1000000 ||
    filters.location !== '';

  return (
    <GlassCard padding="md" className="sticky top-8">
      <div className="space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Filter size={20} className="text-gray-700" />
            <h3 className="text-lg font-semibold text-gray-900">Filters</h3>
          </div>
          {hasActiveFilters && (
            <button
              onClick={clearFilters}
              className="text-sm text-gray-600 hover:text-gray-900 transition-colors"
            >
              Clear all
            </button>
          )}
        </div>

        {/* Industry Filter */}
        <div>
          <h4 className="text-sm font-semibold text-gray-800 mb-3">Industry</h4>
          <div className="space-y-2 max-h-64 overflow-y-auto">
            {industryOptions.map((industry) => (
              <label
                key={industry}
                className="flex items-center gap-2 cursor-pointer group"
              >
                <input
                  type="checkbox"
                  checked={filters.industries.includes(industry)}
                  onChange={() => handleIndustryToggle(industry)}
                  className="w-4 h-4 rounded border-gray-300 text-[#667eea] focus:ring-[#667eea]/20"
                />
                <span className="text-sm text-gray-700 group-hover:text-gray-900">
                  {industry}
                </span>
              </label>
            ))}
          </div>
        </div>

        {/* Budget Range Filter */}
        <div>
          <h4 className="text-sm font-semibold text-gray-800 mb-3">Budget Range</h4>
          <div className="space-y-3">
            <div>
              <label className="text-xs text-gray-600 mb-1 block">Minimum ($)</label>
              <input
                type="number"
                value={filters.budgetRange.min}
                onChange={(e) => handleBudgetChange('min', e.target.value)}
                className="w-full bg-white/20 backdrop-blur-sm border border-white/30 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#667eea]/20"
                placeholder="0"
                min="0"
              />
            </div>
            <div>
              <label className="text-xs text-gray-600 mb-1 block">Maximum ($)</label>
              <input
                type="number"
                value={filters.budgetRange.max}
                onChange={(e) => handleBudgetChange('max', e.target.value)}
                className="w-full bg-white/20 backdrop-blur-sm border border-white/30 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#667eea]/20"
                placeholder="1000000"
                min="0"
              />
            </div>
          </div>
        </div>

        {/* Location Filter */}
        <div>
          <h4 className="text-sm font-semibold text-gray-800 mb-3">Location</h4>
          <input
            type="text"
            value={filters.location}
            onChange={handleLocationChange}
            className="w-full bg-white/20 backdrop-blur-sm border border-white/30 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#667eea]/20"
            placeholder="e.g., San Francisco, CA"
          />
        </div>

        {/* Active Filters Summary */}
        {hasActiveFilters && (
          <div className="pt-4 border-t border-white/30">
            <p className="text-xs text-gray-600 mb-2">Active Filters:</p>
            <div className="flex flex-wrap gap-2">
              {filters.industries.map((industry) => (
                <span
                  key={industry}
                  className="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-[#667eea]/10 text-xs text-[#667eea] font-medium"
                >
                  {industry}
                  <button
                    onClick={() => handleIndustryToggle(industry)}
                    className="hover:text-[#764ba2]"
                  >
                    <X size={12} />
                  </button>
                </span>
              ))}
            </div>
          </div>
        )}
      </div>
    </GlassCard>
  );
}

'use client';

import React from 'react';
import { Building2, MapPin, DollarSign, Sparkles } from 'lucide-react';
import { GlassCard } from '@/components/shared/GlassCard';
import { GlassButton } from '@/components/shared/GlassButton';
import { Sponsor } from '@/types/sponsor';
import { clsx } from 'clsx';

interface SponsorCardProps {
  sponsor: Sponsor;
  matchPercentage: number;
  onConnect?: () => void;
}

export function SponsorCard({ sponsor, matchPercentage, onConnect }: SponsorCardProps) {
  const getMatchColor = (percentage: number) => {
    if (percentage >= 70) return 'text-green-600 bg-green-50';
    if (percentage >= 50) return 'text-yellow-600 bg-yellow-50';
    return 'text-red-600 bg-red-50';
  };

  const getMatchGradient = (percentage: number) => {
    if (percentage >= 70) return 'from-green-500 to-green-600';
    if (percentage >= 50) return 'from-yellow-500 to-yellow-600';
    return 'from-red-500 to-red-600';
  };

  const formatBudget = (min: number, max: number) => {
    const formatNumber = (num: number) => {
      if (num >= 1000000) return `$${(num / 1000000).toFixed(1)}M`;
      if (num >= 1000) return `$${(num / 1000).toFixed(0)}K`;
      return `$${num}`;
    };
    return `${formatNumber(min)} - ${formatNumber(max)}`;
  };

  return (
    <GlassCard padding="md" hover>
      <div className="space-y-4">
        {/* Header with Logo and Match Score */}
        <div className="flex items-start justify-between">
          <div className="flex items-center gap-3">
            {sponsor.logoUrl ? (
              <div className="w-12 h-12 rounded-xl overflow-hidden bg-white">
                <img
                  src={sponsor.logoUrl}
                  alt={sponsor.companyName}
                  className="w-full h-full object-cover"
                />
              </div>
            ) : (
              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-[#667eea] to-[#764ba2] flex items-center justify-center">
                <Building2 size={24} className="text-white" />
              </div>
            )}
            <div>
              <h3 className="text-lg font-bold text-gray-900">{sponsor.companyName}</h3>
              <p className="text-sm text-gray-600">{sponsor.industry}</p>
            </div>
          </div>

          {/* Match Percentage Badge */}
          <div
            className={clsx(
              'flex items-center gap-1 px-3 py-1.5 rounded-full font-bold text-sm',
              getMatchColor(matchPercentage)
            )}
          >
            <Sparkles size={14} />
            <span>{matchPercentage}%</span>
          </div>
        </div>

        {/* Details */}
        <div className="space-y-2">
          <div className="flex items-center gap-2 text-sm text-gray-700">
            <DollarSign size={16} className="text-gray-500" />
            <span>{formatBudget(sponsor.budgetRange.min, sponsor.budgetRange.max)}</span>
          </div>

          <div className="flex items-center gap-2 text-sm text-gray-700">
            <MapPin size={16} className="text-gray-500" />
            <span>{sponsor.location}</span>
          </div>
        </div>

        {/* Preferences */}
        {sponsor.preferences.categories.length > 0 && (
          <div>
            <p className="text-xs text-gray-600 mb-2">Interested in:</p>
            <div className="flex flex-wrap gap-2">
              {sponsor.preferences.categories.slice(0, 3).map((category) => (
                <span
                  key={category}
                  className="px-2 py-1 rounded-lg bg-white/40 text-xs font-medium text-gray-700"
                >
                  {category.replace('-', ' ')}
                </span>
              ))}
              {sponsor.preferences.categories.length > 3 && (
                <span className="px-2 py-1 rounded-lg bg-white/40 text-xs font-medium text-gray-700">
                  +{sponsor.preferences.categories.length - 3} more
                </span>
              )}
            </div>
          </div>
        )}

        {/* Match Score Bar */}
        <div>
          <div className="flex items-center justify-between text-xs text-gray-600 mb-1">
            <span>Match Score</span>
            <span className="font-semibold">{matchPercentage}%</span>
          </div>
          <div className="w-full h-2 bg-white/40 rounded-full overflow-hidden">
            <div
              className={clsx(
                'h-full bg-gradient-to-r transition-all duration-500',
                getMatchGradient(matchPercentage)
              )}
              style={{ width: `${matchPercentage}%` }}
            />
          </div>
        </div>

        {/* Connect Button */}
        {onConnect && (
          <GlassButton
            variant="primary"
            size="sm"
            onClick={onConnect}
            className="w-full"
          >
            Connect
          </GlassButton>
        )}
      </div>
    </GlassCard>
  );
}

'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Building2, MapPin, DollarSign, Sparkles, Target } from 'lucide-react';
import { useRouter } from 'next/navigation';
import { Sponsor } from '@/types/sponsor';
import { GlassButton } from '@/components/shared/GlassButton';
import { createMatch } from '@/lib/api-client';

interface SponsorDetailsModalProps {
  sponsor: Sponsor | null;
  matchScore: number;
  isOpen: boolean;
  onClose: () => void;
  eventId?: string;
}

export function SponsorDetailsModal({ sponsor, matchScore, isOpen, onClose, eventId }: SponsorDetailsModalProps) {
  const [isConnecting, setIsConnecting] = useState(false);
  const router = useRouter();

  if (!sponsor) return null;

  const handleConnect = async () => {
    if (!eventId) {
      alert('Event ID is required to create a match');
      return;
    }

    setIsConnecting(true);
    try {
      await createMatch(eventId, sponsor.id);
      onClose();
      router.push('/organizer/chat');
    } catch (error) {
      console.error('Error creating match:', error);
      alert(error instanceof Error ? error.message : 'Failed to create match');
    } finally {
      setIsConnecting(false);
    }
  };

  const formatBudget = (min: number, max: number) => {
    const formatNumber = (num: number) => {
      if (num >= 1000000) return `$${(num / 1000000).toFixed(1)}M`;
      if (num >= 1000) return `$${(num / 1000).toFixed(0)}K`;
      return `$${num}`;
    };
    return `${formatNumber(min)} - ${formatNumber(max)}`;
  };

  const getMatchColor = (score: number) => {
    if (score >= 70) return 'text-green-600 bg-green-50';
    if (score >= 50) return 'text-yellow-600 bg-yellow-50';
    return 'text-red-600 bg-red-50';
  };

  const getCategoryLabel = (category: string) => {
    return category
      .split('-')
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50"
          />

          {/* Modal */}
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              className="bg-white/90 backdrop-blur-2xl rounded-3xl shadow-2xl border border-white/20 max-w-2xl w-full max-h-[90vh] overflow-y-auto"
            >
              {/* Header */}
              <div className="relative p-8 bg-gradient-to-br from-indigo-50 to-purple-50 rounded-t-3xl border-b border-indigo-100">
                {/* Close Button */}
                <button
                  onClick={onClose}
                  className="absolute top-4 right-4 p-2 rounded-full bg-white/90 backdrop-blur-sm hover:bg-white transition-colors"
                >
                  <X size={20} />
                </button>

                {/* Match Score Badge */}
                <div className="absolute top-4 left-4">
                  <div className={`flex items-center gap-1 px-3 py-1.5 rounded-full font-bold text-sm backdrop-blur-md ${getMatchColor(matchScore)}`}>
                    <Sparkles size={14} />
                    <span>{matchScore}% Match</span>
                  </div>
                </div>

                {/* Company Info */}
                <div className="flex items-center gap-4 mt-8">
                  {sponsor.logoUrl ? (
                    <div className="w-20 h-20 rounded-2xl overflow-hidden bg-white shadow-lg">
                      <img
                        src={sponsor.logoUrl}
