interface EventDiscoveryCardProps {
  event: Event;
  matchScore: number;
  onViewDetails: () => void;
}

export function EventDiscoveryCard({ event, matchScore, onViewDetails }: EventDiscoveryCardProps) {
  const getMatchColor = (score: number) => {
    if (score >= 70) return 'text-green-600 bg-green-50';
    if (score >= 50) return 'text-yellow-600 bg-yellow-50';
    return 'text-red-600 bg-red-50';
  };

  const getMatchGradient = (score: number) => {
    if (score >= 70) return 'from-green-500 to-green-600';
    if (score >= 50) return 'from-yellow-500 to-yellow-600';
    return 'from-red-500 to-red-600';
  };

  const formatDate = (date: Date) => {
    return new Date(date).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    });
  };

  const formatAudience = (size: number) => {
    if (size >= 1000) return `${(size / 1000).toFixed(1)}K`;
    return `${size}`;
  };

  const getCategoryLabel = (category: string) => {
    return category
      .split('-')
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  };

  return (
    <GlassCard padding="md" hover>
      <div className="space-y-4">
        {/* Banner Image or Gradient */}
        <div className="relative h-40 rounded-2xl overflow-hidden">
          {event.bannerUrl ? (
            <img
              src={event.bannerUrl}
              alt={event.name}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-[#667eea] to-[#764ba2]" />
          )}
          <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />

          {/* Match Score Badge */}
          <div className="absolute top-3 right-3">
            <div
              className={clsx(
                'flex items-center gap-1 px-3 py-1.5 rounded-full font-bold text-sm backdrop-blur-md',
                getMatchColor(matchScore)
              )}
            >
              <Sparkles size={14} />
              <span>{matchScore}%</span>
            </div>
          </div>

          {/* Category Badge */}
          <div className="absolute bottom-3 left-3">
            <span className="px-3 py-1 rounded-full bg-white/90 backdrop-blur-sm text-xs font-semibold text-gray-900">
              {getCategoryLabel(event.category)}
            </span>
          </div>
        </div>

        {/* Event Title */}
        <div>
          <h3 className="text-lg font-bold text-gray-900 mb-1">{event.name}</h3>
          <p className="text-sm text-gray-600 line-clamp-2">{event.description}</p>
        </div>

        {/* Event Details */}
        <div className="space-y-2">
          <div className="flex items-center gap-2 text-sm text-gray-700">
            <Calendar size={16} className="text-gray-500" />
            <span>{formatDate(event.date)}</span>
          </div>

          <div className="flex items-center gap-2 text-sm text-gray-700">
            <MapPin size={16} className="text-gray-500" />
            <span>{event.location}</span>
          </div>

          <div className="flex items-center gap-2 text-sm text-gray-700">
            <Users size={16} className="text-gray-500" />
            <span>{formatAudience(event.audienceSize)} attendees</span>
          </div>
        </div>

        {/* Sponsorship Requirements Preview */}
        <div className="pt-3 border-t border-white/30">
          <p className="text-xs text-gray-600 mb-1">Sponsorship Requirements:</p>
          <p className="text-sm text-gray-700 line-clamp-2">
            {event.sponsorshipRequirements}
          </p>
        </div>

        {/* Match Score Bar */}
        <div>
          <div className="flex items-center justify-between text-xs text-gray-600 mb-1">
            <span>Match Score</span>
            <span className="font-semibold">{matchScore}%</span>
          </div>
          <div className="w-full h-2 bg-white/40 rounded-full overflow-hidden">
            <div
              className={clsx(
                'h-full bg-gradient-to-r transition-all duration-500',
                getMatchGradient(matchScore)
              )}
              style={{ width: `${matchScore}%` }}
            />
          </div>
        </div>

        {/* View Details Button */}
        <GlassButton
          variant="primary"
          size="sm"
          onClick={onViewDetails}
          className="w-full"
        >
          View Details
        </GlassButton>
      </div>
    </GlassCard>
  );
}

'use client';

import React from 'react';
import { motion } from 'framer-motion';
import { Filter, X } from 'lucide-react';
import { GlassCard } from '@/components/shared/GlassCard';
import { EventCategory } from '@/types/event';

export interface EventFilters {
  categories: EventCategory[];
  audienceRange: {
    min: number;
    max: number;
  };
  location: string;
  budgetDistribution: string;
}

interface FilterPanelProps {
  filters: EventFilters;
  onFilterChange: (filters: EventFilters) => void;
}

const categoryOptions: { value: EventCategory; label: string }[] = [
  { value: 'college-fest', label: 'College Fest' },
  { value: 'competition', label: 'Competition' },
  { value: 'sports', label: 'Sports' },
  { value: 'hackathon', label: 'Hackathon' },
  { value: 'cultural', label: 'Cultural' },
  { value: 'workshop', label: 'Workshop' },
];

const budgetDistributionOptions = [
  'Any',
  'Low (< $25K)',
  'Medium ($25K - $100K)',
  'High (> $100K)',
];

export function FilterPanel({ filters, onFilterChange }: FilterPanelProps) {
  const handleCategoryToggle = (category: EventCategory) => {
    const newCategories = filters.categories.includes(category)
      ? filters.categories.filter((c) => c !== category)
      : [...filters.categories, category];

    onFilterChange({
      ...filters,
      categories: newCategories,
    });
  };

  const handleAudienceChange = (type: 'min' | 'max', value: string) => {
    const numValue = parseInt(value) || 0;
    onFilterChange({
      ...filters,
      audienceRange: {
        ...filters.audienceRange,
        [type]: numValue,
      },
    });
  };

  const handleLocationChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onFilterChange({
      ...filters,
      location: e.target.value,
    });
  };

  const handleBudgetDistributionChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onFilterChange({
      ...filters,
      budgetDistribution: e.target.value,
    });
  };

  const clearFilters = () => {
    onFilterChange({
      categories: [],
      audienceRange: { min: 0, max: 10000 },
      location: '',
      budgetDistribution: 'Any',
    });
  };

  const hasActiveFilters =
    filters.categories.length > 0 ||
    filters.audienceRange.min > 0 ||
    filters.audienceRange.max < 10000 ||
    filters.location !== '' ||
    filters.budgetDistribution !== 'Any';

  return (
    <GlassCard padding="md" className="sticky top-8">
      <div className="space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Filter size={20} className="text-gray-700" />
            <h3 className="text-lg font-semibold text-gray-900">Filters</h3>
          </div>
          {hasActiveFilters && (
            <button
              onClick={clearFilters}
              className="text-sm text-gray-600 hover:text-gray-900 transition-colors"
            >
              Clear all
            </button>
          )}
        </div>

        {/* Category Filter */}
        <div>
          <h4 className="text-sm font-semibold text-gray-800 mb-3">Category</h4>
          <div className="space-y-2">
            {categoryOptions.map((option) => (
              <label
                key={option.value}
                className="flex items-center gap-2 cursor-pointer group"
              >
                <input
                  type="checkbox"
                  checked={filters.categories.includes(option.value)}
                  onChange={() => handleCategoryToggle(option.value)}
                  className="w-4 h-4 rounded border-gray-300 text-[#667eea] focus:ring-[#667eea]/20"
                />
                <span className="text-sm text-gray-700 group-hover:text-gray-900">
                  {option.label}
                </span>
              </label>
            ))}
          </div>
        </div>

        {/* Audience Size Filter */}
        <div>
          <h4 className="text-sm font-semibold text-gray-800 mb-3">Audience Size</h4>
          <div className="space-y-3">
            <div>
              <label className="text-xs text-gray-600 mb-1 block">Minimum</label>
              <input
                type="number"
                value={filters.audienceRange.min}
                onChange={(e) => handleAudienceChange('min', e.target.value)}
                className="w-full bg-white/20 backdrop-blur-sm border border-white/30 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#667eea]/20"
                placeholder="0"
                min="0"
              />
            </div>
            <div>
              <label className="text-xs text-gray-600 mb-1 block">Maximum</label>
              <input
                type="number"
                value={filters.audienceRange.max}
                onChange={(e) => handleAudienceChange('max', e.target.value)}
                className="w-full bg-white/20 backdrop-blur-sm border border-white/30 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#667eea]/20"
                placeholder="10000"
                min="0"
              />
            </div>
          </div>
        </div>

        {/* Location Filter */}
        <div>
          <h4 className="text-sm font-semibold text-gray-800 mb-3">Location</h4>
          <input
            type="text"
            value={filters.location}
            onChange={handleLocationChange}
            className="w-full bg-white/20 backdrop-blur-sm border border-white/30 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#667eea]/20"
            placeholder="e.g., San Francisco, CA"
          />
        </div>

        {/* Budget Distribution Filter */}
        <div>
          <h4 className="text-sm font-semibold text-gray-800 mb-3">Budget Distribution</h4>
          <select
            value={filters.budgetDistribution}
            onChange={handleBudgetDistributionChange}
            className="w-full bg-white/20 backdrop-blur-sm border border-white/30 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#667eea]/20"
          >
            {budgetDistributionOptions.map((option) => (
              <option key={option} value={option}>
                {option}
              </option>
            ))}
          </select>
        </div>

        {/* Active Filters Summary */}
        {hasActiveFilters && (
          <div className="pt-4 border-t border-white/30">
            <p className="text-xs text-gray-600 mb-2">Active Filters:</p>
            <div className="flex flex-wrap gap-2">
              {filters.categories.map((category) => (
                <span
                  key={category}
                  className="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-[#667eea]/10 text-xs text-[#667eea] font-medium"
                >
                  {categoryOptions.find((c) => c.value === category)?.label}
                  <button
                    onClick={() => handleCategoryToggle(category)}
                    className="hover:text-[#764ba2]"
                  >
                    <X size={12} />
                  </button>
                </span>
              ))}
            </div>
          </div>
        )}
      </div>
    </GlassCard>
  );
}

'use client';

import { useEffect } from 'react';
import { clearAllAuthData } from '@/lib/auth';

export function useAuthCleanup() {
  useEffect(() => {
    // Clean up auth data on page load if it's corrupted
    const cleanupCorruptedAuth = () => {
      try {
        const userStr = localStorage.getItem('current_user');
        if (userStr) {
          const user = JSON.parse(userStr);
          // Check if user data is corrupted or incomplete
          if (!user.id || !user.email || !user.role || 
              (user.role !== 'organizer' && user.role !== 'sponsor')) {
            clearAllAuthData();
          }
        }
      } catch (error) {
        // If parsing fails, clear all auth data
        clearAllAuthData();
      }
    };

    cleanupCorruptedAuth();

    // Set up periodic session validation
    const interval = setInterval(() => {
      try {
        const userStr = localStorage.getItem('current_user');
        if (userStr) {
          const user = JSON.parse(userStr);
          const SESSION_TIMEOUT = 24 * 60 * 60 * 1000; // 24 hours

          if (user.timestamp && (Date.now() - user.timestamp > SESSION_TIMEOUT)) {
            clearAllAuthData();
            window.location.href = '/login';
          }
        }
      } catch (error) {
        clearAllAuthData();
      }
    }, 5 * 60 * 1000); // Check every 5 minutes

    return () => clearInterval(interval);
  }, []);
}

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/utils/supabase/client';
import { getMatchMessages, sendLocalMessage } from '@/lib/localStorage-chat';

interface Message {
  id: string;
  match_id: string;
  sender_id: string;
  content: string;
  created_at: string;
}

export function useChat(matchId: string | null) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [loading, setLoading] = useState(false);
  const supabase = createClient();

  const fetchMessages = useCallback(async () => {
    if (!matchId) return;
    setLoading(true);

    // Use localStorage fallback if configured
    if (process.env.NEXT_PUBLIC_USE_LOCALSTORAGE === 'true') {
      const localMessages = getMatchMessages(matchId);
      const formattedMessages: Message[] = localMessages.map(msg => ({
        id: msg.id,
        match_id: msg.matchId,
        sender_id: msg.senderId,
        content: msg.content,
        created_at: msg.createdAt
      }));
      setMessages(formattedMessages);
      setLoading(false);
      return;
    }

    const { data } = await supabase.from('messages').select('*').eq('match_id', matchId).order('created_at');
    if (data) setMessages(data);
    setLoading(false);
  }, [matchId, supabase]);

  useEffect(() => {
    if (!matchId) return;

    fetchMessages();

    if (process.env.NEXT_PUBLIC_USE_LOCALSTORAGE !== 'true') {
      const channel = supabase
        .channel(`match:${matchId}`)
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages', filter: `match_id=eq.${matchId}` },
          (payload: any) => setMessages(prev => [...prev, payload.new as Message]))
        .subscribe();

      return () => { supabase.removeChannel(channel); };
    }
  }, [matchId, fetchMessages, supabase]);

  const sendMessage = async (content: string) => {
    if (!matchId) return;

    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    // Use localStorage fallback if configured
    if (process.env.NEXT_PUBLIC_USE_LOCALSTORAGE === 'true') {
      const newMessage = sendLocalMessage(matchId, user.id, content);
      const formattedMessage: Message = {
        id: newMessage.id,
        match_id: newMessage.matchId,
        sender_id: newMessage.senderId,
        content: newMessage.content,
        created_at: newMessage.createdAt
      };
      setMessages(prev => [...prev, formattedMessage]);
      return;
    }

    await supabase.from('messages').insert({ match_id: matchId, sender_id: user.id, content });
  };

  return { messages, loading, sendMessage };
}

