import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/utils/supabase/client';
import { getUserMatches, getMatchMessages } from '@/lib/localStorage-chat';

interface Conversation {
  id: string;
  participantName: string;
  participantAvatar?: string;
  lastMessage: string;
  lastMessageTime: Date;
  unreadCount: number;
}

export function useConversations() {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [loading, setLoading] = useState(true);
  const supabase = createClient();

  const fetchConversations = useCallback(async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
      setLoading(false);
      return;
    }

    // Use localStorage fallback if configured
    if (process.env.NEXT_PUBLIC_USE_LOCALSTORAGE === 'true') {
      // Need to get role from somewhere if not in user object, but user_metadata has it
      const role = user.user_metadata.role;
      const matches = getUserMatches(user.id, role as 'organizer' | 'sponsor');
      const convos: Conversation[] = matches.map(match => {
        const messages = getMatchMessages(match.id);
        const lastMessage = messages[messages.length - 1];
        return {
          id: match.id,
          participantName: role === 'organizer' ? 'Demo Sponsor' : 'Demo Event',
          lastMessage: lastMessage?.content || 'No messages yet',
          lastMessageTime: lastMessage ? new Date(lastMessage.createdAt) : new Date(match.createdAt),
          unreadCount: 0
        };
      });
      setConversations(convos.sort((a, b) => b.lastMessageTime.getTime() - a.lastMessageTime.getTime()));
      setLoading(false);
      return;
    }

    const { data: profile } = await supabase.from('profiles').select('role').eq('id', user.id).single();
    if (!profile) {
      setLoading(false);
      return;
    }

    const query = supabase.from('matches').select(`
      id, status, created_at,
      events!inner(id, name, organizer_id),
      sponsors!inner(id, company_name, user_id)
    `).eq('status', 'accepted');

    if (profile.role === 'organizer') {
      query.eq('events.organizer_id', user.id);
    } else {
      query.eq('sponsors.user_id', user.id);
    }

    const { data: matches } = await query;
    if (!matches) {
      setLoading(false);
      return;
    }

    const convos: Conversation[] = await Promise.all(matches.map(async (m: any) => {
      const { data: msgs } = await supabase.from('messages').select('content, created_at').eq('match_id', m.id).order('created_at', { ascending: false }).limit(1);
      return {
        id: m.id,
        participantName: profile.role === 'organizer' ? m.sponsors.company_name : m.events.name,
        lastMessage: msgs?.[0]?.content || 'No messages yet',
        lastMessageTime: msgs?.[0] ? new Date(msgs[0].created_at) : new Date(m.created_at),
        unreadCount: 0
      };
    }));

    setConversations(convos.sort((a, b) => b.lastMessageTime.getTime() - a.lastMessageTime.getTime()));
    setLoading(false);
  }, [supabase]);

  useEffect(() => {
    fetchConversations();
  }, [fetchConversations]);

  return { conversations, loading, refresh: fetchConversations };
}

import { createClient } from '@/utils/supabase/client';
import { Event } from '@/types/event';

export const analyticsApi = {
    async getOrganizerStats() {
        const supabase = createClient();
        const { data: { user } } = await supabase.auth.getUser();

        if (!user) {
            return {
                totalEvents: 0,
                matches: 0,
                messages: 0,
                pendingDeliverables: 0,
            };
        }

        // 1. Total Events
        const { count: totalEvents } = await supabase
            .from('events')
            .select('*', { count: 'exact', head: true })
            .eq('organizer_id', user.id);

        // 2. Matches (linked to user's events)
        const { count: matches } = await supabase
            .from('matches')
            .select('*, events!inner(organizer_id)', { count: 'exact', head: true })
            .eq('events.organizer_id', user.id);

        // 3. Messages (sent by user - simple metric)
        const { count: messages } = await supabase
            .from('messages')
            .select('*', { count: 'exact', head: true })
            .eq('sender_id', user.id);

        // 4. Pending Deliverables (linked to user's events)
        const { count: pendingDeliverables } = await supabase
            .from('deliverables')
            .select('*, matches!inner(events!inner(organizer_id))', { count: 'exact', head: true })
            .eq('matches.events.organizer_id', user.id)
            .eq('status', 'pending');

        return {
            totalEvents: totalEvents || 0,
            matches: matches || 0,
            messages: messages || 0,
            pendingDeliverables: pendingDeliverables || 0,
        };
    },

    async getDashboardEvents(): Promise<Event[]> {
        const supabase = createClient();
        const { data: { user } } = await supabase.auth.getUser();

        if (!user) return [];

        const { data, error } = await supabase
            .from('events')
            .select('*')
            .eq('organizer_id', user.id)
            .order('created_at', { ascending: false })
            .limit(6);

        if (error) {
            console.error('Error fetching dashboard events:', error);
            return [];
        }

        // Map database fields to frontend type if necessary
        // Assuming Event type matches DB schema mostly, but let's be safe
        return data.map((e: any) => ({
            id: e.id,
            organizerId: e.organizer_id,
            name: e.name,
            category: e.category,
            location: e.location,
            audienceSize: e.audience_size,
            date: new Date(e.date),
            description: e.description,
            sponsorshipRequirements: e.sponsorship_requirements,
            bannerUrl: e.banner_url,
            status: e.status,
            createdAt: new Date(e.created_at),
            updatedAt: new Date(e.updated_at),
        }));
    },

    async getSponsorStats() {
        const supabase = createClient();
        const { data: { user } } = await supabase.auth.getUser();

        if (!user) {
            return {
                eventsMatched: 0,
                pendingApprovals: 0,
                messages: 0,
            };
        }

        // 1. Events Matched (Sponsorships)
        const { count: eventsMatched } = await supabase
            .from('matches')
            .select('*, sponsors!inner(user_id)', { count: 'exact', head: true })
            .eq('sponsors.user_id', user.id);

        // 2. Pending Approvals (Deliverables)
        const { count: pendingApprovals } = await supabase
            .from('deliverables')
            .select('*, matches!inner(sponsors!inner(user_id))', { count: 'exact', head: true })
            .eq('matches.sponsors.user_id', user.id)
            .eq('status', 'pending');

        // 3. Messages (sent by user)
        const { count: messages } = await supabase
            .from('messages')
            .select('*', { count: 'exact', head: true })
            .eq('sender_id', user.id);

        return {
            eventsMatched: eventsMatched || 0,
            pendingApprovals: pendingApprovals || 0,
            messages: messages || 0,
        };
    },

    async getRecommendedEvents(): Promise<Event[]> {
        const supabase = createClient();

        const { data, error } = await supabase
            .from('events')
            .select('*')
            .eq('status', 'published')
            .order('created_at', { ascending: false })
            .limit(6);

        if (error) {
            console.error('Error fetching recommended events:', error);
            return [];
        }

        return data.map((e: any) => ({
            id: e.id,
            organizerId: e.organizer_id,
            name: e.name,
            category: e.category,
            location: e.location,
            audienceSize: e.audience_size,
            date: new Date(e.date),
            description: e.description,
            sponsorshipRequirements: e.sponsorship_requirements,
            bannerUrl: e.banner_url,
            status: e.status,
            createdAt: new Date(e.created_at),
            updatedAt: new Date(e.updated_at),
        }));
    }
};

import { createClient } from '@/utils/supabase/client';
import { Deliverable, DeliverableStatus } from '@/types/deliverable';

export const deliverablesApi = {
    async getDeliverables(role: 'organizer' | 'sponsor'): Promise<Deliverable[]> {
        const supabase = createClient();
        const { data: { user } } = await supabase.auth.getUser();

        if (!user) return [];

        // Fetch deliverables with joined data
        const { data, error } = await supabase
            .from('deliverables')
            .select(`
        *,
        matches!inner (
          id,
          events (
            name,
            organizer_id,
            profiles (name)
          ),
          sponsors (company_name, user_id)
        )
      `)
            .order('due_date', { ascending: true });

        if (error) {
            console.error('Error fetching deliverables:', error);
            return [];
        }

        // Filter based on role (RLS should handle this, but double check)
        // and transform to frontend type
        return data.map((d: any) => ({
            id: d.id,
            matchId: d.match_id,
            title: d.title,
            description: d.description,
            proofUrl: d.proof_url,
            status: d.status as DeliverableStatus,
            feedback: d.feedback,
            dueDate: new Date(d.due_date),
            createdAt: new Date(d.created_at),
            updatedAt: new Date(d.updated_at),
            sponsorName: d.matches?.sponsors?.company_name,
            eventName: d.matches?.events?.name,
            organizerName: d.matches?.events?.profiles?.name,
        }));
    },

    async uploadProof(id: string, file: File): Promise<string | null> {
        const supabase = createClient();

        // 1. Upload file
        const fileExt = file.name.split('.').pop();
        const fileName = `${id}-${Math.random()}.${fileExt}`;
        const filePath = `${fileName}`;

        const { error: uploadError } = await supabase.storage
            .from('deliverable-proofs')
            .upload(filePath, file);

        if (uploadError) {
            console.error('Error uploading proof:', uploadError);
            throw uploadError;
        }

        // 2. Get public URL
        const { data: { publicUrl } } = supabase.storage
            .from('deliverable-proofs')
            .getPublicUrl(filePath);

        // 3. Update deliverable record
        const { error: updateError } = await supabase
            .from('deliverables')
            .update({
                proof_url: publicUrl,
                status: 'submitted',
                updated_at: new Date().toISOString(),
            })
            .eq('id', id);

        if (updateError) {
            console.error('Error updating deliverable:', updateError);
            throw updateError;
        }

        return publicUrl;
    },

    async updateStatus(id: string, status: DeliverableStatus, feedback?: string): Promise<void> {
        const supabase = createClient();

        const updates: any = {
            status,
            updated_at: new Date().toISOString(),
        };

        if (feedback) {
            updates.feedback = feedback;
        }

        const { error } = await supabase
            .from('deliverables')
            .update(updates)
            .eq('id', id);

        if (error) {
            console.error('Error updating status:', error);
            throw error;
        }
    }
};

import { createClient } from '@/utils/supabase/client';

export interface Notification {
    id: string;
    userId: string;
    title: string;
    message: string;
    link?: string;
    read: boolean;
    createdAt: Date;
}

export const notificationsApi = {
    async getNotifications(): Promise<Notification[]> {
        const supabase = createClient();
        const { data: { user } } = await supabase.auth.getUser();

        if (!user) return [];

        const { data, error } = await supabase
            .from('notifications')
            .select('*')
            .eq('user_id', user.id)
            .order('created_at', { ascending: false })
            .limit(20);

        if (error) {
            console.error('Error fetching notifications:', error);
            return [];
        }

        return data.map((n: any) => ({
            id: n.id,
            userId: n.user_id,
            title: n.title,
            message: n.message,
            link: n.link,
            read: n.read,
            createdAt: new Date(n.created_at),
        }));
    },

    async markAsRead(id: string): Promise<void> {
        const supabase = createClient();

        const { error } = await supabase
            .from('notifications')
            .update({ read: true })
            .eq('id', id);

        if (error) {
            console.error('Error marking notification as read:', error);
            throw error;
        }
    },

    async markAllAsRead(): Promise<void> {
        const supabase = createClient();
        const { data: { user } } = await supabase.auth.getUser();

        if (!user) return;

        const { error } = await supabase
            .from('notifications')
            .update({ read: true })
            .eq('user_id', user.id)
            .eq('read', false);

        if (error) {
            console.error('Error marking all notifications as read:', error);
            throw error;
        }
    }
};

import { createBrowserClient } from '@supabase/ssr'

export function createClient() {
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

    if (!supabaseUrl || !supabaseKey) {
        console.warn('Supabase credentials missing. Using mock client for demo mode.');
        return {
            auth: {
                signInWithPassword: async ({ email, password }: any) => {
                    // Mock successful login for demo accounts
                    if (
                        (email === 'test.organizer@test.com' && password === 'iamorganizer') ||
                        (email === 'test.sponser@test.com' && password === 'iamsponser')
                    ) {
                        const role = email.includes('organizer') ? 'organizer' : 'sponsor';
                        return {
                            data: {
                                user: {
                                    id: 'demo-user',
                                    email,
                                    user_metadata: { role },
                                },
                                session: { access_token: 'demo-token' },
                            },
                            error: null,
                        };
                    }
                    return { data: { user: null }, error: { message: 'Invalid credentials' } };
                },
                signOut: async () => ({ error: null }),
                getUser: async () => ({
                    data: {
                        user: {
                            id: 'demo-user',
                            email: 'test.organizer@test.com',
                            user_metadata: { role: 'organizer' }
                        }
                    },
                    error: null
                }),
                getSession: async () => ({
                    data: {
                        session: {
                            access_token: 'demo-token',
                            user: {
                                id: 'demo-user',
                                user_metadata: { role: 'organizer' }
                            }
                        }
                    },
                    error: null
                }),
                onAuthStateChange: () => ({ data: { subscription: { unsubscribe: () => { } } } }),
            },
            from: () => ({
                select: () => ({
                    eq: () => ({
                        single: () => ({ data: null, error: null }),
                        order: () => ({ data: [], error: null }),
                    }),
                }),
            }),
        } as any;
    }

    return createBrowserClient(supabaseUrl, supabaseKey);
}
